from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential
from typing import List, Dict

REQUIRED_FIELDS = {"Total", "LineItems", "AmountDue"}

def validate_invoice(invoice: Dict) -> List[str]:
    missing = [field for field in REQUIRED_FIELDS if field not in invoice]
    if missing:
        raise ValueError(f"Missing required fields: {', '.join(missing)}")
    return []

def extract_invoice(text: str) -> Dict:
    endpoint = "https://<YOUR_RESOURCE_NAME>.cognitiveservices.azure.com/"
    key = "<YOUR_KEY>"
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(model_name="prebuilt-invoice", document=text)
    invoice = poller.result()

    result = {}
    for category in invoice.documents[0].categories:
        if category.name == "Table":
            for table in category.tables:
                headers = [field.text for field in table.fields if field.kind == "header"]
                rows = []
                for field in table.fields:
                    if field.kind == "cell":
                        row = [field.text] + [None] * (len(headers) - 1)
                        row[headers.index(field.header.text)] = field.text
                        rows.append(row)
                result[category.name] = rows

    required_fields = {}
    for row in result.get("Table", []):
        field_name = row[0]
        if field_name in REQUIRED_FIELDS:
            required_fields[field_name] = row[1]

    confidence_issues = validate_invoice(required_fields)
    if confidence_issues:
        raise ValueError("Fields failed validation: " + ", ".join(confidence_issues))

    return required_fields

# Example usage
if __name__ == "__main__":
    import json

    with open("<PATH_TO_INVOICE_IMAGE>", "rb") as img_file:
        invoice_data = extract_invoice(img_file.read())
        print(json.dumps(invoice_data, indent=2))
